-- 同页收件与游标同时提交；重复页/CAS失败不能漏页或产生重复投递。
-- statement
INSERT INTO notification_jobs(job_id,source_kind,source_key,cid_number,created_at,expires_at,updated_at) SELECT NULL,'post','', '',0,1,0 WHERE NOT COALESCE((EXISTS(SELECT 1 FROM notification_jobs WHERE job_id=json_extract(?1,'$.lease.id') AND state='leased' AND lease_token=json_extract(?1,'$.lease.token') AND lease_expires_at>json_extract(?1,'$.now')) AND EXISTS(SELECT 1 FROM notification_jobs WHERE job_id=json_extract(?1,'$.lease.id') AND cursor_created_at IS json_extract(?1,'$.job.cursor_created_at') AND cursor_cid_number IS json_extract(?1,'$.job.cursor_cid_number'))),0);
-- statement
INSERT OR IGNORE INTO notification_deliveries(delivery_id,job_id,cid_number,account_id,binding_revision,device_id,endpoint_revision,updated_at) SELECT json_extract(value,'$.delivery_id'),json_extract(?1,'$.lease.id'),json_extract(value,'$.cid_number'),json_extract(value,'$.account_id'),json_extract(value,'$.binding_revision'),json_extract(value,'$.device_id'),json_extract(value,'$.endpoint_revision'),json_extract(?1,'$.now') FROM json_each(?1,'$.deliveries') WHERE EXISTS(SELECT 1 FROM push_endpoints e WHERE e.cid_number=json_extract(value,'$.cid_number') AND e.device_id=json_extract(value,'$.device_id') AND e.account_id=json_extract(value,'$.account_id') AND e.binding_revision=json_extract(value,'$.binding_revision') AND e.endpoint_revision=json_extract(value,'$.endpoint_revision') AND e.expires_at>json_extract(?1,'$.now'));
-- statement
UPDATE notification_jobs SET state=CASE WHEN json_extract(?1,'$.complete') THEN 'done' ELSE 'pending' END,cursor_created_at=COALESCE(json_extract(?1,'$.cursor.created_at'),cursor_created_at),cursor_cid_number=COALESCE(json_extract(?1,'$.cursor.cid_number'),cursor_cid_number),lease_token=NULL,lease_expires_at=0,attempts=0,next_attempt_at=json_extract(?1,'$.now')+1000,last_dispatched_at=0,updated_at=json_extract(?1,'$.now') WHERE job_id=json_extract(?1,'$.lease.id') AND state='leased' AND lease_token=json_extract(?1,'$.lease.token');
